<div id="permissions" class="section hidden"><div class="mb-6 flex flex-wrap items-center justify-between gap-4"><div><h1 class="text-3xl font-bold">مجوزها</h1><p class="mt-1 text-gray-500">مدیریت قابلیت‌های اتمیک، دامنه و سطح خطر</p></div><button onclick="openAccessPermission()" class="rounded-xl bg-indigo-600 px-5 py-3 text-white"><i class="fas fa-plus ml-2"></i>مجوز جدید</button></div><div class="mb-5 grid gap-3 rounded-3xl bg-white p-4 shadow-sm md:grid-cols-4"><input id="accessPermissionSearch" oninput="renderAccessPermissions()" class="rounded-xl border px-4 py-3" placeholder="جستجوی مجوز..."><select id="accessPermissionScope" onchange="renderAccessPermissions()" class="rounded-xl border px-4"><option value="">همه دامنه‌ها</option><option value="platform">پلتفرم</option><option value="website">سایت</option><option value="academy">آموزشگاه</option><option value="branch">شعبه</option><option value="self">شخصی</option></select><select id="accessPermissionRisk" onchange="renderAccessPermissions()" class="rounded-xl border px-4"><option value="">همه سطوح خطر</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select><div id="accessPermissionCount" class="flex items-center text-sm text-gray-500"></div></div><div class="overflow-hidden rounded-3xl bg-white shadow"><div class="overflow-x-auto"><table class="w-full min-w-[1050px]"><thead class="bg-gray-50"><tr><th class="p-4 text-right">عنوان و نام</th><th class="p-4 text-right">منبع</th><th class="p-4 text-right">عملیات</th><th class="p-4 text-right">دامنه</th><th class="p-4 text-right">خطر</th><th class="p-4"></th></tr></thead><tbody id="accessPermissionsBody" class="divide-y text-sm"></tbody></table></div></div></div>
